struct Params {
  t: f32, // @default 0  The card's clock, seconds.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;
fn toLinear(c: vec3f) -> vec3f {
  return select(pow((c + vec3f(0.055)) / 1.055, vec3f(2.4)), c / 12.92, c <= vec3f(0.04045));
}
fn toDisplay(c: vec3f) -> vec3f {
  return select(1.055 * pow(max(c, vec3f(0.0)), vec3f(1.0 / 2.4)) - vec3f(0.055), c * 12.92, c <= vec3f(0.0031308));
}
fn grainAt(p: vec2f, t: f32) -> f32 {
  let q = fract(sin(dot(floor(p) + vec2f(t * 37.0, t * 91.0), vec2f(12.9898, 78.233))) * 43758.5453);
  return q - 0.5;
}

// the hairlines' x (reference px): C, O (two), C, O (two), O (two), then the N's two
const LINES = array<f32, 10>(374.5, 591.5, 650.5, 811.5, 1028.5, 1087.5, 1249.5, 1307.5, 1471.0, 1524.0);
const BASE = 385.0;

fn hairline(p: vec2f, x: f32, len: f32, level: f32) -> f32 {
  let k = BASE - p.y;
  if (k < 0.0 || len <= 0.0) { return 0.0; }
  let across = exp(-(p.x - x) * (p.x - x) / (2.0 * 1.6 * 1.6));
  // brighter at the letter, easing off upward, a soft top
  let along = (0.6 + 0.4 * (1.0 - clamp(k / max(len, 1.0), 0.0, 1.0))) * smoothstep(len, len - 14.0, k);
  return level * across * along;
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let p = uv * vec2f(1920.0, 818.0);
  let f = floor(params.t * 24.0 + 0.001);
  // the strobe-off tail
  let off = f == 49.0 || f == 51.0 || f == 53.0 || f >= 55.0;
  var shown = select(1.0, 0.0, off);
  let type_ = toDisplay(textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb).r * 0.976;
  // C and O: climbing from 145 px a little slower than the N, fading out over the first 15 frames
  let fade = clamp(1.0 - f / 15.0, 0.0, 1.0);
  var lines = 0.0;
  for (var i = 0; i < 8; i = i + 1) {
    lines = max(lines, hairline(p, LINES[i], min(145.0 + 23.0 * f, BASE), 0.29 * fade));
  }
  // N: climbing to the top by frame 9, holding, snapping back at 16 and settling;
  // the two flash frames (52, 54) throw the full lines back
  var nLen = 11.0 + 21.0 * exp(-(f - 16.0) / 7.0);
  if (f < 16.0) { nLen = min(145.0 + 27.5 * f, BASE); }
  if (f == 52.0 || f == 54.0) { nLen = BASE; }
  let nLevel = select(0.6, 0.45, f >= 16.0 && f != 52.0 && f != 54.0);
  lines = max(lines, hairline(p, LINES[8], nLen, nLevel));
  lines = max(lines, hairline(p, LINES[9], nLen, nLevel));
  let grain = grainAt(p, params.t) * 0.006;
  let display = clamp(max(type_, lines) * shown + grain + 0.002, 0.0, 1.0);
  return vec4f(toLinear(vec3f(display)), 1.0);
}

struct Params {
  mist: f32, // @default 0  Share of the near glow mixed into the picture (halation, bloom), in linear light.
  mistWide: f32, // @default 0  Share of the wide glow mixed in: the haze veil that lifts the dark round every light.
  toe: f32, // @default 1  Gamma on display level before the curve (< 1 opens the shadows).
  contrast: f32, // @default 1  Slope around the pivot (< 1 is flatter).
  pivot: f32, // @default 0.45  Display level the contrast turns about.
  lift: f32, // @default 0  Where black lands (display level): the flat veil.
  white: f32, // @default 1  Where white lands (display level): the washed top.
  saturation: f32, // @default 1  Chroma kept in the mids and highlights.
  shadowSaturation: f32, // @default 1  Chroma kept in the shadows.
  shadowTint: vec3f, // @default 0  Added to the shadows (display level).
  midTint: vec3f, // @default 0  Added to the mids.
  highlightTint: vec3f, // @default 0  Added to the highlights.
  grain: f32, // @default 0  Grain amount (the grade's formula: heavier in the blacks, a new pattern every frame).
  grainSize: f32, // @default 1.3  Grain cell size in pixels of the render.
};
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;

// More textures are bound unfilterable: bilinear by hand.
fn bilerp(t: texture_2d<f32>, uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(t));
  let p = uv * size - 0.5;
  let i = floor(p);
  let f = p - i;
  let hi = vec2i(size) - vec2i(1);
  let a = vec2i(i);
  let c00 = textureLoad(t, clamp(a, vec2i(0), hi), 0).rgb;
  let c10 = textureLoad(t, clamp(a + vec2i(1, 0), vec2i(0), hi), 0).rgb;
  let c01 = textureLoad(t, clamp(a + vec2i(0, 1), vec2i(0), hi), 0).rgb;
  let c11 = textureLoad(t, clamp(a + vec2i(1, 1), vec2i(0), hi), 0).rgb;
  return mix(mix(c00, c10, f.x), mix(c01, c11, f.x), f.y);
}

// The Output encodes sRGB, so "display level" here is exactly the sRGB value the viewer sees
// (a 2.2 power instead put a 0.022 lift at level 1 of 255, not 5.6: the toes part ways near black).
fn toDisplay(l: vec3f) -> vec3f {
  return select(1.055 * pow(l, vec3f(1.0 / 2.4)) - 0.055, 12.92 * l, l <= vec3f(0.0031308));
}

fn toLinear(d: vec3f) -> vec3f {
  return select(pow((d + 0.055) / 1.055, vec3f(2.4)), d / 12.92, d <= vec3f(0.04045));
}

fn luma(c: vec3f) -> f32 {
  return dot(c, vec3f(0.2126, 0.7152, 0.0722));
}

fn grainHash(p: vec3f) -> f32 {
  var q = fract(p * vec3f(0.1031, 0.1030, 0.0973));
  q = q + dot(q, q.yxz + 33.33);
  return fract((q.x + q.y) * q.z);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lin = max(textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb, vec3f(0.0));
  let near = bilerp(inputTexture1, uv);
  let wide = bilerp(inputTexture2, uv);
  // the mist, in linear light: the lights' glow and the veil round them
  let m = lin * (1.0 - params.mist - params.mistWide) + near * params.mist + wide * params.mistWide;
  // the curve, on display level: toe, contrast about the pivot, then black and white land
  var c = pow(clamp(toDisplay(max(m, vec3f(0.0))), vec3f(0.0), vec3f(1.0)), vec3f(params.toe));
  c = clamp(params.pivot + (c - params.pivot) * params.contrast, vec3f(0.0), vec3f(1.0));
  c = params.lift + (params.white - params.lift) * c;
  // tone bands: a tint added to each
  let y0 = luma(c);
  let ws = 1.0 - smoothstep(0.04, 0.22, y0);
  let wh = smoothstep(0.35, 0.75, y0);
  let wm = clamp(1.0 - ws - wh, 0.0, 1.0);
  c = c + ws * params.shadowTint + wm * params.midTint + wh * params.highlightTint;
  let y = luma(c);
  c = vec3f(y) + (c - vec3f(y)) * mix(params.saturation, params.shadowSaturation, ws);
  // the film's one grain (render.ts adds it after the accumulation under --final, T1432b)
  let px = floor(uv * frameU.resolution / max(params.grainSize, 0.5));
  let n = grainHash(vec3f(px, frameU.absFrame)) + grainHash(vec3f(px + 17.0, frameU.absFrame * 1.7)) - 1.0;
  c = c + vec3f(n) * params.grain * (0.35 + 0.65 * (1.0 - luma(c)));
  c = clamp(c, vec3f(0.0), vec3f(1.0));
  return vec4f(toLinear(c), 1.0);
}

struct Params {
  gain: f32, // @default 1  Scales the downsampled picture.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  // one output texel's footprint in uv
  let foot = vec2f(abs(dpdx(uv).x), abs(dpdy(uv).y));
  var sum = vec3f(0.0);
  for (var j = 0; j < 4; j = j + 1) {
    for (var i = 0; i < 4; i = i + 1) {
      let o = (vec2f(f32(i), f32(j)) + 0.5) / 4.0 - 0.5;
      sum = sum + max(textureSampleLevel(inputTexture, inputSampler, uv + o * foot, 0.0).rgb, vec3f(0.0));
    }
  }
  return vec4f(sum / 16.0 * params.gain, 1.0);
}

struct Params {
  bars: f32, // @default 3  Radiance of the vertical light bars.
  barCount: f32, // @default 22  Bars around the horizon.
  roof: f32, // @default 0.006  Radiance of the roof.
  floor: f32, // @default 0.002  Radiance below the horizon.
  white: f32, // @default 0  1 = the white cyc room instead.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

fn barHash(i: f32) -> f32 {
  return fract(sin(i * 91.3458 + 7.1) * 47453.5453);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let unused = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).a * 0.0;
  let phi = (uv.x - 0.5) * 6.2831853;
  let theta = uv.y * 3.1415927;
  let d = vec3f(sin(theta) * sin(phi), cos(theta), -sin(theta) * cos(phi));
  if (params.white > 0.5) {
    let wall = mix(0.55, 1.0, smoothstep(-0.3, 0.4, d.y));
    return vec4f(vec3f(wall * 1.6) + vec3f(unused), 1.0);
  }
  var radiance = mix(vec3f(params.floor), vec3f(params.roof), smoothstep(-0.05, 0.2, d.y));
  // Vertical bars: each its own azimuth jitter, width and height.
  let slot = uv.x * params.barCount;
  let index = floor(slot);
  let within = fract(slot) - 0.5 - (barHash(index) - 0.5) * 0.6;
  let width = 0.05 + 0.06 * barHash(index + 3.0);
  let top = 0.1 + 0.35 * barHash(index + 7.0);
  let lit = step(0.35, barHash(index + 11.0));
  let bar = smoothstep(width, width * 0.4, abs(within)) * smoothstep(-0.08, -0.04, d.y) * (1.0 - smoothstep(top - 0.04, top, d.y)) * lit;
  radiance = radiance + vec3f(0.92, 0.96, 1.0) * params.bars * bar;
  return vec4f(radiance + vec3f(unused), 1.0);
}

struct Params {
  gain: f32, // @default 1  Radiance of the type.
};

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  o.albedo = vec4f(0.0, 0.0, 0.0, 1.0);
  o.emissive = vec3f(p.gain);
  o.roughness = 1.0;
  o.metallic = 0.0;
  return o;
}
